#include <stdio.h>

#define MAX(a, b) ((a) > (b) ? (a) : (b))

int main() {
    int n;
    scanf("%d", &n);

    // 这里wealth长度定义为n+1，是为了让wealth数组索引对应成员编号 1~N
    int wealth[n + 1];
    int family[n + 1];
    for (int i = 1; i <= n; i++) {
        scanf("%d", &wealth[i]);
        family[i] = wealth[i];
    }

    for (int i = 0; i < n - 1; i++) {
        int fa, ch;
        scanf("%d %d", &fa, &ch);
        family[fa] += wealth[ch];
    }

    int max = family[1];
    for (int i = 2; i <= n; i++) {
        max = MAX(max, family[i]);
    }

    printf("%d\n", max);

    return 0;
}
